mkdir -p "$TMPDIR/scratch" && cat > "$TMPDIR/scratch/Probe.java" <<'EOF'
import com.google.gson.internal.ConstructorConstructor;
import com.google.gson.internal.ObjectConstructor;
import com.google.gson.reflect.TypeToken;
import java.util.*;

public class Probe {
  interface MyInterface {}
  static abstract class MyAbstract {}
  static class ThrowingCtor { ThrowingCtor() { throw new IllegalStateException("boom"); } }
  static class HasArgCtor {
    int x;
    HasArgCtor(int x) { this.x = x; }
  }

  public static void main(String[] args) throws Exception {
    ConstructorConstructor cc = new ConstructorConstructor(new HashMap<java.lang.reflect.Type, com.google.gson.InstanceCreator<?>>());

    try {
      Object o = cc.get(TypeToken.get(MyInterface.class)).construct();
      System.out.println("interface construct returned: " + o);
    } catch (Throwable t) {
      System.out.println("interface construct threw: " + t.getClass().getName() + " : " + t.getMessage() + " cause=" + t.getCause());
    }

    try {
      Object o = cc.get(TypeToken.get(MyAbstract.class)).construct();
      System.out.println("abstract construct returned: " + o);
    } catch (Throwable t) {
      System.out.println("abstract construct threw: " + t.getClass().getName() + " : " + t.getMessage() + " cause=" + t.getCause());
    }

    try {
      Object o = cc.get(TypeToken.get(ThrowingCtor.class)).construct();
      System.out.println("throwing ctor construct returned: " + o);
    } catch (Throwable t) {
      System.out.println("throwing ctor construct threw: " + t.getClass().getName() + " : " + t.getMessage() + " cause=" + t.getCause());
    }

    try {
      Object o = cc.get(TypeToken.get(HasArgCtor.class)).construct();
      System.out.println("hasArgCtor construct returned: " + o + " class=" + o.getClass() + " x=" + ((HasArgCtor)o).x);
    } catch (Throwable t) {
      System.out.println("hasArgCtor construct threw: " + t.getClass().getName() + " : " + t.getMessage() + " cause=" + t.getCause());
    }
  }
}
EOF
cd /tmp/w-DewkUWAd && javac -cp target/classes -d "$TMPDIR/scratch" "$TMPDIR/scratch/Probe.java" && java -cp "target/classes:$TMPDIR/scratch" Probe
